import{_ as l,a0 as p,w as d,s as o,ao as r,I as t,x as a,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"通过 find 命令找到你要找的东西 | LCTT x X-CMD","titleTemplate":false,"description":"通过 find 命令找到你要找的东西 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"通过 find 命令找到你要找的东西 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"通过 find 命令找到你要找的东西 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200219 How to find what you-re looking for on Linux with find","title":"通过 find 命令找到你要找的东西","tag":"202003","desc":""},"relativePath":"202003/20200219 How to find what you-re looking for on Linux with find.md","filePath":"[post].md"}'),h={name:"202003/20200219 How to find what you-re looking for on Linux with find.md"};function c(g,s,k,b,u,f){const e=p("Link");return d(),o("div",null,[s[15]||(s[15]=r(`<h1 id="通过-find-命令找到你要找的东西" tabindex="-1">通过 find 命令找到你要找的东西 <a class="header-anchor" href="#通过-find-命令找到你要找的东西" aria-label="Permalink to “通过 find 命令找到你要找的东西”">​</a></h1><blockquote><p>find 命令有巨多的选项可以帮助你准确定位你在 Linux 系统上需要寻找的文件。这篇文章讨论了一系列非常有用的选项。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202003/06/113842txki5llopb5aagbt.jpg" alt=""></p><p>在 Linux 系统上有许多用于查找文件的命令，而你在使用它们时也有巨多的选项可以使用。</p><p>例如，你不仅可以通过文件的名称来查找文件，还可以通过文件的所有者或者组、它们的创建时间、大小、分配的权限、最后一次访问它们的时间、关联的信息节点，甚至是文件是否属于系统上不再存在的帐户或组等等来查找文件。</p><p>你还可以指定搜索从哪里开始，搜索应该深入到文件系统的什么位置，以及搜索结果将告诉你它所找到的文件的数量。</p><p>而所有这些要求都可以通过 <code>find</code> 命令来处理。</p><p>下面提供了根据这些要求查找文件的示例。在某些命令中，错误（例如试图列出你没有读取权限的文件）输出将被发送到 <code>/dev/null</code>，以便我们不必查看它。或者，我们可以简单地以 root 身份运行以避免这个问题。</p><p>请记住，还有更多的其他选项。这篇文章涵盖了很多内容，但并不是 <code>find</code> 命令帮助你定位查找文件的所有方式。</p><h3 id="选择起点" tabindex="-1">选择起点 <a class="header-anchor" href="#选择起点" aria-label="Permalink to “选择起点”">​</a></h3><p>使用 <code>find</code>，你可以选择一个起点或从你所在的位置开始。要选择的搜索的起点，请在单词 <code>find</code> 后输入它。例如，<code>find /usr</code> 或 <code>find ./bin</code> 将在 <code>/usr</code> 目录或当前位置下的 <code>bin</code> 目录开始搜索，而 <code>find ~</code> 将在你的主目录中开始搜索，即使你当前位于当前文件系统中的其他位置。</p><h3 id="选择你要找的" tabindex="-1">选择你要找的 <a class="header-anchor" href="#选择你要找的" aria-label="Permalink to “选择你要找的”">​</a></h3><p>最常用的搜索策略之一是按名称搜索文件。这需要使用 <code>-name</code> 选项。</p><p>默认情况下，<code>find</code> 会显示找到的文件的完整路径。如果你在命令中添加 <code>-print</code>，你会看到同样的结果。如果你想查看与文件相关的详细信息—-例如：文件的长度、权限等，你需要在你的 <code>find</code> 命令的末尾添加 <code>-ls</code> 参数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find ~/bin -name tryme</span></span>
<span class="line"><span>/home/shs/bin/tryme</span></span>
<span class="line"><span>$ find ~/bin -name tryme -print</span></span>
<span class="line"><span>/home/shs/bin/tryme</span></span>
<span class="line"><span>$ find ~/bin -name tryme -ls</span></span>
<span class="line"><span>   917528   4 -rwx------   1 shs    shs   139 Apr  8  2019 /home/shs/bin/tryme</span></span></code></pre></div><p>你也可以使用子字符串来查找文件。例如，如果你将上面示例中的 <code>tryme</code> 替换为 <code>try*</code>，你将会找到所有名称以 <code>try</code> 开头的文件。（LCTT 译注：如果要使用通配符 <code>*</code> ，请将搜索字符串放到单引号或双引号内，以避免通配符被 shell 所解释）</p><p>按名称查找文件可能是 <code>find</code> 命令最典型的用法，不过还有很多其他的方式来查找文件，并且有这样做的需要。下面的部分展示了如何使用其他可用的方式。</p><p>此外，当按文件大小、组、索引节点等条件来搜索文件时，你需要确认找到的文件与你要查找的文件是否相匹配。使用 <code>-ls</code> 选项来显示细节是非常有用。</p><h3 id="通过大小查找文件" tabindex="-1">通过大小查找文件 <a class="header-anchor" href="#通过大小查找文件" aria-label="Permalink to “通过大小查找文件”">​</a></h3><p>按大小查找文件需要使用 <code>-size</code> 选项并且对相应规范使用一点技巧。例如，如果你指定 <code>-size 189b</code>，你将找到 189 个块大小的文件，而不是 189 个字节。（LCTT 译注：如果不跟上单位，默认单位是 <code>b</code>。一个块是 512 个字节大小，不足或正好 512 个字节将占据一个块。）对于字节，你需要使用 <code>--size 189c</code>（字符）。而且，如果你指定 <code>--size 200w</code> ，你将会找到 200 个“<ruby>字<rt>word</rt></ruby>”的文件——以“双字节增量”为单位的字，而不是“我们互相谈论的那些事情”中的单词。你还可以通过以千字节（<code>k</code>）、兆字节（<code>M</code>）和千兆字节（<code>G</code>）为单位提供大小来查找文件。（LCTT 译注：乃至还有 <code>T</code>、<code>P</code>）</p><p>大多数情况下，Linux 用户会搜索比选定大小要大的文件。例如，要查找大于 1 千兆字节的文件，你可以使用这样的命令，其中 <code>+1G</code> 表示“大于 1 千兆字节”:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find -size +1G -ls 2&gt;/dev/null</span></span>
<span class="line"><span>  787715 1053976 -rw-rw-r-- 1 shs  shs  1079263432 Dec 21  2018 ./backup.zip</span></span>
<span class="line"><span>  801834 1052556 -rw-rw-r-- 1 shs  shs  1077809525 Dec 21  2018 ./2019/hold.zip</span></span></code></pre></div><h3 id="通过索引节点号查找文件" tabindex="-1">通过索引节点号查找文件 <a class="header-anchor" href="#通过索引节点号查找文件" aria-label="Permalink to “通过索引节点号查找文件”">​</a></h3><p>你可以通过用于维护文件元数据（即除文件内容和文件名之外的所有内容）的索引节点来查找文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find -inum 919674 -ls 2&gt;/dev/null</span></span>
<span class="line"><span>  919674  4 -rw-rw-r--  1 shs  shs   512 Dec 27 15:25 ./bin/my.log</span></span></code></pre></div><h3 id="查找具有特定文件所有者或组的文件" tabindex="-1">查找具有特定文件所有者或组的文件 <a class="header-anchor" href="#查找具有特定文件所有者或组的文件" aria-label="Permalink to “查找具有特定文件所有者或组的文件”">​</a></h3><p>按所有者或组查找文件也非常简单。这里我们使用 <code>sudo</code> 来解决权限问题。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo find /home -user nemo -name &quot;*.png&quot; -ls</span></span>
<span class="line"><span> 1705219  4 drwxr-xr-x  2 nemo nemo  4096 Jan 28 08:50 /home/nemo/Pictures/me.png</span></span></code></pre></div><p>在下面这个命令中，我们寻找一个被称为 <code>admins</code> 的多用户组拥有的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find /tmp -group admins -ls</span></span>
<span class="line"><span>   262199      4 -rwxr-x---   1 dory     admins         27 Feb 16 18:57 /tmp/testscript</span></span></code></pre></div><h3 id="查找没有所有者或组的文件" tabindex="-1">查找没有所有者或组的文件 <a class="header-anchor" href="#查找没有所有者或组的文件" aria-label="Permalink to “查找没有所有者或组的文件”">​</a></h3><p>你可以使用如下命令所示的 <code>-nouser</code> 选项来查找不属于当前系统上的任何用户的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find /tmp -nouser -ls</span></span>
<span class="line"><span>262204 4 -rwx------ 1 1016 1016 17 Feb 17 16:42 /tmp/hello</span></span></code></pre></div><p>请注意，该列表显示了旧用户的 UID 和 GID，这清楚地表明该用户未在系统上定义。这种命令将查找帐户已从系统中删除的用户创建在主目录之外的文件，或者在用户帐户被删除后而未被删除的主目录中创建的文件。类似地，<code>-nogroup</code> 选项也会找到这样的文件，尤其是当这些用户是相关组的唯一成员时。</p><h3 id="按上次更新时间查找文件" tabindex="-1">按上次更新时间查找文件 <a class="header-anchor" href="#按上次更新时间查找文件" aria-label="Permalink to “按上次更新时间查找文件”">​</a></h3><p>在此命令中，我们在特定用户的主目录中查找过去 24 小时内更新过的文件。<code>sudo</code> 用于搜索另一个用户的主目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo find /home/nemo -mtime -1</span></span>
<span class="line"><span>/home/nemo</span></span>
<span class="line"><span>/home/nemo/snap/cheat</span></span>
<span class="line"><span>/home/nemo/tryme</span></span></code></pre></div><h3 id="按上次更改权限的时间查找文件" tabindex="-1">按上次更改权限的时间查找文件 <a class="header-anchor" href="#按上次更改权限的时间查找文件" aria-label="Permalink to “按上次更改权限的时间查找文件”">​</a></h3><p><code>-ctime</code> 选项可以帮助你查找在某个参考时间范围内状态（如权限）发生更改的文件。以下是查找在最后一天内权限发生更改的文件的示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -ctime -1 -ls</span></span>
<span class="line"><span>   787987   4 -rwxr-xr-x   1 shs   shs     189 Feb 11 07:31 ./tryme</span></span></code></pre></div><p>请记住，显示的日期和时间只反映了对文件内容进行的最后更新。你需要使用像 <code>stat</code> 这样的命令来查看与文件相关联的三个状态（文件创建、修改和状态更改）。</p><h3 id="按上次访问的时间查找文件" tabindex="-1">按上次访问的时间查找文件 <a class="header-anchor" href="#按上次访问的时间查找文件" aria-label="Permalink to “按上次访问的时间查找文件”">​</a></h3><p>在这个命令中，我们使用 <code>-atime</code> 选项查找在过去两天内访问过的本地 pdf 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find -name &quot;*.pdf&quot; -atime -2</span></span>
<span class="line"><span>./Wingding_Invites.pdf</span></span></code></pre></div><h3 id="根据文件相对于另一个文件的时间来查找文件" tabindex="-1">根据文件相对于另一个文件的时间来查找文件 <a class="header-anchor" href="#根据文件相对于另一个文件的时间来查找文件" aria-label="Permalink to “根据文件相对于另一个文件的时间来查找文件”">​</a></h3><p>你可以使用 <code>-newer</code> 选项来查找比其他文件更新的文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -newer dig1 -ls</span></span>
<span class="line"><span>   786434     68 drwxr-xr-x  67 shs      shs         69632 Feb 16 19:05 .</span></span>
<span class="line"><span>  1064442      4 drwxr-xr-x   5 shs      shs          4096 Feb 16 11:06 ./snap/cheat</span></span>
<span class="line"><span>   791846      4 -rw-rw-r--   1 shs      shs           649 Feb 13 14:26 ./dig</span></span></code></pre></div><p>没有相应的 <code>-older</code> 选项，但是你可以用 <code>! -newer</code> （即更旧）得到类似的结果，它们基本上一样。</p><h3 id="按类型查找文件" tabindex="-1">按类型查找文件 <a class="header-anchor" href="#按类型查找文件" aria-label="Permalink to “按类型查找文件”">​</a></h3><p>通过文件类型找到一个文件，你有很多选项——常规文件、目录、块和字符文件等等。以下是文件类型选项列表:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>b      块特殊文件（缓冲的）</span></span>
<span class="line"><span>c      字符特殊文件（无缓冲的）</span></span>
<span class="line"><span>d      目录</span></span>
<span class="line"><span>p      命名管道（FIFO）</span></span>
<span class="line"><span>f      常规文件</span></span>
<span class="line"><span>l      符号链接</span></span>
<span class="line"><span>s      套接字</span></span></code></pre></div><p>这里有一个寻找符号链接的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -type l -ls</span></span>
<span class="line"><span>   805717   0 lrwxrwxrwx   1 shs    shs    11 Apr 10  2019 ./volcano -&gt; volcano.pdf</span></span>
<span class="line"><span>   918552   0 lrwxrwxrwx   1 shs    shs     1 Jun 16  2018 ./letter -&gt; pers/letter2mom</span></span></code></pre></div><h3 id="限制查找的深度" tabindex="-1">限制查找的深度 <a class="header-anchor" href="#限制查找的深度" aria-label="Permalink to “限制查找的深度”">​</a></h3><p><code>-mindepth</code> 和 <code>-maxdepth</code> 选项控制在文件系统中搜索的深度（从当前位置或起始点开始）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find -maxdepth 3 -name &quot;*loop&quot;</span></span>
<span class="line"><span>./bin/save/oldloop</span></span>
<span class="line"><span>./bin/long-loop</span></span>
<span class="line"><span>./private/loop</span></span></code></pre></div><h3 id="查找空文件" tabindex="-1">查找空文件 <a class="header-anchor" href="#查找空文件" aria-label="Permalink to “查找空文件”">​</a></h3><p>在这个命令中，我们寻找空文件，但不进入目录及其子目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -maxdepth 2 -empty -type f -ls</span></span>
<span class="line"><span>   917517      0 -rw-rw-r--   1 shs   shs      0 Sep 23 11:00 ./complaints/newfile</span></span>
<span class="line"><span>   792050      0 -rw-rw-r--   1 shs   shs      0 Oct  4 19:02 ./junk</span></span></code></pre></div><h3 id="按权限查找文件" tabindex="-1">按权限查找文件 <a class="header-anchor" href="#按权限查找文件" aria-label="Permalink to “按权限查找文件”">​</a></h3><p>你可以使用 <code>-perm</code> 选项查找具有特定权限集的文件。在下面的示例中，我们只查找常规文件（<code>-type f</code>），以避免看到符号链接，默认情况下符号链接被赋予了这种权限，即使它们所引用的文件是受限的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find -perm 777 -type f -ls</span></span>
<span class="line"><span>find: ‘./.dbus’: Permission denied</span></span>
<span class="line"><span>   798748      4 -rwxrwxrwx   1 shs      shs            15 Mar 28  2019 ./runme</span></span></code></pre></div><h3 id="使用查找来帮助你删除文件" tabindex="-1">使用查找来帮助你删除文件 <a class="header-anchor" href="#使用查找来帮助你删除文件" aria-label="Permalink to “使用查找来帮助你删除文件”">​</a></h3><p>如果使用如下命令，你可以使用 <code>find</code> 命令定位并删除文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -name runme -exec rm {} \\;</span></span></code></pre></div><p><code>{}</code> 代表根据搜索条件找到的每个文件的名称。</p><p>一个非常有用的选项是将 <code>-exec</code> 替换为 <code>-ok</code>。当你这样做时，<code>find</code> 会在删除任何文件之前要求确认。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ find . -name runme -ok rm -rf {} \\;</span></span>
<span class="line"><span>&lt; rm ... ./bin/runme &gt; ?</span></span></code></pre></div><p>删除文件并不是 <code>-ok</code> 和 <code>-exec</code> 能为你做的唯一事情。例如，你可以复制、重命名或移动文件。</p><p>确实有很多选择可以有效地使用 <code>find</code> 命令，毫无疑问还有一些在本文中没有涉及到。我希望你已经找到一些新的，特别有帮助的。</p><hr>`,71)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),n(e,{href:"https://www.networkworld.com/article/3527420/how-to-find-what-you-re-looking-for-on-linux-with-find.html"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3527420/how-to-find-what-you-re-looking-for-on-linux-with-find.html",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),n(e,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),n(e,{href:"https://github.com/heguangzhi"},{default:i(()=>[...s[4]||(s[4]=[a("heguangzhi",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const w=l(h,[["render",c]]);export{y as __pageData,w as default};
